mod query_neutralization_key_epoch_tests {
    use super::*;
    fn key() -> Key {
        let bytes: Vec<u8> = [Fr::ONE,Fr::from(2u64)].into_iter().flat_map(|v|v.0.into_iter().flat_map(u64::to_le_bytes)).collect();
        Key::build(Points::Kernel([&[];5]),&bytes).unwrap()
