    fn generations_survive_moves_and_change_on_mutation_or_new_key() {
        let first=key();let a=first.diagnostic_key_id;assert_ne!(a,0);
        let mut moved=Box::new(first);assert_eq!(moved.diagnostic_key_id,a);
        moved.invalidate_solver();let b=moved.diagnostic_key_id;assert_ne!(a,b);
